  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.agent.SKILL_OPINION_RECORDING_ENABLED.valueNotes.0": "Désactivé par défaut ; les poids d’agrégation restent inchangés dans les deux cas.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.agent.SKILL_OPINION_RECORDING_ENABLED.valueNotes.1": "Une fois activé, les échantillons sont écrits après agrégation si un history id est lié, et matérialisés depuis le rapport après sauvegarde de l’historique.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.agent.VALUATION_AGENT_TOOL_ENABLED.notes.0": "Désactivé par défaut ; le registre d’outils du processus n’inclut l’outil qu’après activation et redémarrage.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.agent.VALUATION_AGENT_TOOL_ENABLED.notes.1": "Chaque estimation inclut des hypothèses et une plage de sensibilité ; en l’absence de données fondamentales, insufficient_fundamentals est renvoyé plutôt qu’un chiffre inventé.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.agent.VALUATION_AGENT_TOOL_ENABLED.notes.2": "Consultez docs/valuation-models_EN.md pour le contrat de la phase 1 et les étapes de restauration.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.agent.VALUATION_AGENT_TOOL_ENABLED.summary": "Outil Agent DCF et valorisation relative en opt-in, avec hypothèses transparentes.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.agent.VALUATION_AGENT_TOOL_ENABLED.title": "Activer l'outil d'évaluation de l'agent",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.agent.VALUATION_AGENT_TOOL_ENABLED.usage": "Laissez désactivé pour les installations par défaut. Activez uniquement lorsque les Agents doivent appeler estimate_stock_valuation après un redémarrage du processus.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.AGENT_LITELLM_MODEL.impact.0": "Les choix de modèles qui influencent les Q&A des agents, les choix de police et les appels d’outils associés.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.AGENT_LITELLM_MODEL.notes.0": "Assurez-vous que le modèle est accessible via les canaux activés, le routage YAML ou les clés de fournisseur héritées.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.AGENT_LITELLM_MODEL.summary": "Établit un modèle dédié aux flux de travail des agents.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.AGENT_LITELLM_MODEL.title": "Modèle principal d’agent",
