  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.AGENT_LITELLM_MODEL.valueNotes.0": "Utile quand l’agent a besoin d’un raisonnement plus solide ou d’un contexte plus long.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.AGENT_LITELLM_MODEL.valueNotes.1": "Seulement les flux d’agents.",
