  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.anspire_llm.notes.0": "Ne pointez pas l’URL de base vers un autre fournisseur lors de la réutilisation d’un Anspire Clé.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.anspire_llm.summary": "Utilise les clés API Anspire comme passerelle LLM compatible avec OpenAI.",
