  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.anspire_llm.usage": "ANSPIRE_LLM_ENABLED contrôle ce chemin de compatibilité ;ANSPIRE_LLM_BASE_URL définit le point d’arrivée de la passerelle ;ANSPIRE_LLM_MODEL définit le modèle par défaut lorsqu’aucun modèle primaire n’est explicitement sélectionné.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.anspire_llm.valueNotes.0": "Ce chemin est principalement destiné aux configurations simplifiées sans LLM_CHANNELS ou LITELLM_MODEL.",
