  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.LLM_TEMPERATURE.summary": "Contrôle l’aléatoire de la sortie.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.LLM_TEMPERATURE.title": "Température",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.LLM_TEMPERATURE.usage": "Utilisez 0,0 à 2,0. Les valeurs inférieures sont plus déterministes ; les valeurs plus élevées sont plus variées.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.LLM_TEMPERATURE.valueNotes.0": "Utilisez des valeurs basses pour une sortie stable et structurée.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.LLM_TEMPERATURE.valueNotes.1": "0,7 est la valeur par défaut générale.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.LLM_USAGE_HMAC_KEY_VERSION.impact.0": "Évite la comparaison accidentelle entre différents HMAC Clés ou déploiements.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.LLM_USAGE_HMAC_KEY_VERSION.notes.0": "Ce n’est qu’une étiquette de version, pas un secret.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.LLM_USAGE_HMAC_KEY_VERSION.summary": "Indique la version actuelle de la clé HMAC utilisée pour le suivi de l’usage LLM.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.LLM_USAGE_HMAC_KEY_VERSION.title": "LLM Utilisation HMAC Version clé",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.LLM_USAGE_HMAC_KEY_VERSION.usage": "Mettez-le à jour lors de la rotation LLM_USAGE_HMAC_SECRET, par exemple PROD-2026-06.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.LLM_USAGE_HMAC_KEY_VERSION.valueNotes.0": "Par défaut, la version locale est désactivée.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.LLM_USAGE_HMAC_SECRET.impact.0": "Affecte la comparabilité de messages_hmac, system_message_hmac, et user_message_hmac dans llm_usage.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.LLM_USAGE_HMAC_SECRET.notes.0": "Ne réutilisez pas le secret de session de connexion et ne validez ni n’exposez la valeur réelle dans le contrôle de version, les issues, les journaux ou les captures d’écran.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.LLM_USAGE_HMAC_SECRET.summary": "Signe les empreintes HMAC au niveau des messages pour la télémétrie d’utilisation des LLM.",
