  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.LLM_USAGE_HMAC_SECRET.usage": "Laissez généralement ce champ vide afin que le backend crée un fichier secret local. Définissez-le uniquement lorsque les HMAC doivent volontairement être comparables entre déploiements, et utilisez une valeur aléatoire à forte entropie, par exemple générée avec openssl rand -hex 32.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.LLM_USAGE_HMAC_SECRET.valueNotes.0": "Ce secret n’est pas envoyé aux prestataires et ne modifie pas les invites, les paramètres du modèle ou les rapports.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.LLM_USAGE_HMAC_SECRET.valueNotes.1": "Lors de sa rotation, mettez également à jour LLM_USAGE_HMAC_KEY_VERSION.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.LOCAL_CLI_BACKEND_MAX_CONCURRENCY.summary": "Limite le nombre de processus locaux de génération en ligne de commande pouvant démarrer simultanément.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.LOCAL_CLI_BACKEND_MAX_CONCURRENCY.title": "Concurrence Max du Commandement Local",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.LOCAL_CLI_BACKEND_MAX_CONCURRENCY.usage": "Par défaut, c’est 1 pour éviter de démarrer plusieurs locaux CLI traite en même temps et ralentit la machine.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.LOCAL_CLI_BACKEND_MAX_CONCURRENCY.valueNotes.0": "La concurrence finale ne dépasse jamais la concurrence maximale de la génération modèle.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.OPENAI_BASE_URL.impact.0": "Impact OpenAI-Demandes de modèles hérités compatibles sous le chemin de configuration.",
