  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.OPENAI_BASE_URL.title": "OpenAI-URL de base -compatible",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.OPENAI_BASE_URL.usage": "Ça se termine souvent par /v1. Officiel APIs, les passerelles et les services locaux utilisent des URL différentes.",
