  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.OPENAI_BASE_URL.valueNotes.1": "Gemini ou Anthropic Les chemins officiels n’utilisent généralement pas OPENAI_BASE_URL.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.OPENCODE_CLI_MODEL.impact.0": "Affecte l’analyse standard, la revue de marché et la génération de texte via OpenCode CLI. N’affecte pas l’assistant d’interrogation boursière.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.OPENCODE_CLI_MODEL.summary": "Nom de modèle facultatif transmis à OpenCode run avec --model.",
