  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.OPENCODE_CLI_MODEL.usage": "S’applique uniquement lorsque la méthode de génération d’analyse est OpenCode CLI. Laissez ce champ vide pour que StockPulse ne transmette pas --model et qu’OpenCode utilise sa configuration locale par défaut.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.OPENCODE_CLI_MODEL.valueNotes.0": "La disponibilité des modèles et l’authentification sont gérées par votre configuration OpenCode locale.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.OPENCODE_CLI_MODEL.valueNotes.1": "Une fois défini, la valeur est passée comme un seul jeton argv et ne doit pas contenir d’espaces blancs ou de métacaractères de shell.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.provider_keys.impact.0": "Cela affecte les appels de modèles, les tests de connexion et la découverte de modèles disponible pour le fournisseur correspondant.",
