  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.VISION_MODEL.valueNotes.0": "Une valeur historique en dehors du catalogue actuel des modèles est conservée et marquée comme indisponible.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.backtest.BACKTEST_ENABLED.impact.0": "Influence la calibration du poids de la stratégie, la calibration de la mémoire et la génération des rapports backtest.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.backtest.BACKTEST_ENABLED.notes.0": "La fonction de poids automatique de la stratégie de l’agent dépend des données de backtest.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.backtest.BACKTEST_ENABLED.summary": "Permet ou désactive le backtesting d’analyse historique.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.backtest.BACKTEST_ENABLED.title": "Commutateur de backtest",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.backtest.BACKTEST_ENABLED.usage": "Lorsqu’il est activé, le système compare périodiquement les résultats d’analyses passées avec les mouvements réels de prix ultérieurs afin d’évaluer la précision de la stratégie.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.backtest.BACKTEST_ENABLED.valueNotes.0": "Les données de backtest alimentent l’auto-pondération de la stratégie (AGENT_SKILL_AUTOWEIGHT) et la calibration de la mémoire.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.backtest.BACKTEST_ENABLED.valueNotes.1": "La fermeture des backtests n’affecte pas les enregistrements de backtest existants, mais arrête d’évaluer les nouveaux backtests.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.backtest.BACKTEST_ENGINE_VERSION.impact.0": "Affecte l’algorithme d’évaluation et les résultats.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.backtest.BACKTEST_ENGINE_VERSION.notes.0": "Gardez la valeur par défaut sauf indication de changer de version.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.backtest.BACKTEST_ENGINE_VERSION.summary": "Label de version moteur rétro.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.backtest.BACKTEST_ENGINE_VERSION.title": "Version rétrotest du moteur",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.backtest.BACKTEST_ENGINE_VERSION.usage": "En général, pas besoin de changer. L’étiquette identifie la version actuelle de la logique d’évaluation.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.backtest.BACKTEST_ENGINE_VERSION.valueNotes.0": "Différentes versions peuvent utiliser des algorithmes d’évaluation ou des règles de jugement différents.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.backtest.eval_params.impact.0": "Influence les critères de jugement rétroactif, la couverture et le calcul du poids de la stratégie.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.backtest.eval_params.notes.0": "Les trois paramètres influencent conjointement les résultats des tests rétro ; Ajustez-les ensemble.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.backtest.eval_params.summary": "Contrôle la fenêtre d’évaluation, l’âge minimum de l’enregistrement et la bande de retour neutre.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.backtest.eval_params.title": "Paramètres d’évaluation du backtest",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.backtest.eval_params.usage": "BACKTEST_EVAL_WINDOW_DAYS fixe la fenêtre des jours de bourse ;BACKTEST_MIN_AGE_DAYS n’évalue que les dossiers plus anciens que cela ;BACKTEST_NEUTRAL_BAND_PCT Définit le pourcentage de la bande de retour neutre.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.backtest.eval_params.valueNotes.0": "Des fenêtres d’évaluation plus longues incluent plus de jours de négociation et produisent des résultats plus stables mais retardés.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.backtest.eval_params.valueNotes.1": "BACKTEST_MIN_AGE_DAYS Exclut les analyses très récentes jusqu’à ce que suffisamment de données de suivi sur les prix soient disponibles.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.backtest.eval_params.valueNotes.2": "Les rendements compris dans BACKTEST_NEUTRAL_BAND_PCT sont qualifiés de neutres et ne sont jugés ni corrects ni incorrects.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.base.STOCK_LIST.impact.0": "Affecte la portée de l’analyse, le contenu des notifications et les rapports d’historique sauvegardés.",
