  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.base.STOCK_LIST.title": "Liste des actions sélectionnées",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.base.STOCK_LIST.usage": "Les virgules anglaises sont recommandées. Les virgules chinoises collées, les virgules d’énumération, les points-virgules, les espaces et les nouvelles lignes sont également reconnus et normalisés en virgules anglaises lorsqu’ils sont enregistrés.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.base.STOCK_LIST.valueNotes.0": "Le mode planifié relit la valeur STOCK_LIST enregistrée avant chaque exécution.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.base.STOCK_LIST.valueNotes.1": "Si la ligne de commande est temporairement passée --stocks, seule cette opération manuelle est affectée ; les tâches futures prévues ne seront pas verrouillées.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.base.STOCK_LIST.valueNotes.2": "STOCK_GROUP_N devrait être un sous-ensemble de STOCK_LIST et n’affecte que le routage des e-mails groupés.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.data_source.ALPHASIFT_ENABLED.impact.0": "Affecte l’accès à la sélection Web, le chargement des stratégies AlphaSift et l’API de sélection.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.data_source.ALPHASIFT_ENABLED.notes.0": "AlphaSift génère les candidats et StockPulse les enrichit avec les cours, les fondamentaux et le contexte d’actualité ; sa désactivation n’affecte pas les analyses, rapports ou notifications existants.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.data_source.ALPHASIFT_ENABLED.summary": "Contrôle la page intégrée de sélection d’actions AlphaSift.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.data_source.ALPHASIFT_ENABLED.title": "Sélection AlphaSift",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.data_source.ALPHASIFT_ENABLED.usage": "Désactivé par défaut. Lorsque la valeur est true, l’application Web vérifie qu’alphasift.dsa_adapter est installé avec les dépendances du backend. S’il manque, exécutez depuis la racine du dépôt, dans l’ordre, python -m pip install --upgrade --constraint constraints.txt pip, python -m pip install --build-constraint build-constraints.txt -r requirements.txt et python -m pip check, ou reconstruisez l’artefact du backend.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.data_source.ALPHASIFT_ENABLED.valueNotes.0": "AlphaSift est installé comme dépendance du backend StockPulse ; /install est conservé uniquement comme action de réparation explicite.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.data_source.ALPHASIFT_ENABLED.valueNotes.1": "Les résultats de la sélection d’actions sont uniquement à des fins de recherche et ne constituent pas un conseil en investissement.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.data_source.ALPHASIFT_INSTALL_SPEC.impact.0": "Affecte la validation de la source de l’adaptateur AlphaSift et les installations de réparation explicites.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.data_source.ALPHASIFT_INSTALL_SPEC.notes.0": "Utilisez uniquement une source fiable. AlphaSift est une fonction expérimentale de sélection ; comprenez les risques avant de l’activer.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.data_source.ALPHASIFT_INSTALL_SPEC.summary": "Configure la source pip fiable d’AlphaSift utilisée par les installations de réparation explicites.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.data_source.ALPHASIFT_INSTALL_SPEC.title": "Source d’installation AlphaSift",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.data_source.ALPHASIFT_INSTALL_SPEC.usage": "Utilise par défaut un commit ZhuLinsen/alphasift vérifié. Les déploiements normaux installent AlphaSift via requirements ; cette source n’est utilisée que lorsque le point de terminaison d’installation de réparation est appelé manuellement.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.data_source.ALPHASIFT_INSTALL_SPEC.valueNotes.0": "Le point de terminaison de réparation ne gère pas les chemins locaux ni les wheels personnalisés ; installez-les d’abord dans l’environnement Python du backend.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.data_source.ALPHASIFT_INSTALL_SPEC.valueNotes.1": "Ce champ est considéré comme sensible, donc la page des paramètres n’affiche pas la valeur complète.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.data_source.BIAS_THRESHOLD.impact.0": "Affecte les avertissements d’analyse technique concernant la poursuite, la déviation de MA et les conseils de trading.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.data_source.BIAS_THRESHOLD.notes.0": "Trop bas peut ajouter des avertissements bruyants ; Trop élevé peut affaiblir les alertes de risque de poursuite.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.data_source.BIAS_THRESHOLD.summary": "Fixe le seuil d’alerte de risque pour la déviation de prix par rapport à MA5.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.data_source.BIAS_THRESHOLD.title": "Seuil de BIAS",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.data_source.BIAS_THRESHOLD.usage": "Entrez un pourcentage. Lorsque l’écart du prix par rapport à la MA5 dépasse le seuil, les rapports peuvent déconseiller de poursuivre la hausse ou signaler un risque de retour à la moyenne.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.data_source.BIAS_THRESHOLD.valueNotes.0": "Les actions à forte tendance peuvent assouplir de manière appropriée les seuils selon les règles de runtime.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.data_source.ENABLE_CHIP_DISTRIBUTION.impact.0": "Influence la distribution des puces et l’analyse des zones de coût dans les rapports.",
