  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.agent.RISK_GATE_PROFILE.valueNotes.1": "La porte ne peut pas être désactivée et les erreurs internes échouent en mode fermé.",
  "utils.systemConfigI18n.fieldOptionLabelMaps.RISK_GATE_PROFILE.aggressive": "Offensif",
  "utils.systemConfigI18n.fieldOptionLabelMaps.RISK_GATE_PROFILE.balanced": "Équilibré",
  "utils.systemConfigI18n.fieldOptionLabelMaps.RISK_GATE_PROFILE.conservative": "Prudent",
  "utils.systemConfigI18n.fieldTitleMaps.RISK_GATE_PROFILE": "Profil du gestionnaire de risque",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.indicators.INDICATOR_MA_PERIODS.impact.0": "Influe sur la classification de tendance, les écarts, les contrôles de support et les valeurs MA du rapport.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.indicators.INDICATOR_MA_PERIODS.notes.0": "Avec un historique suffisant, les valeurs par défaut conservent le comportement MA antérieur.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.indicators.INDICATOR_MA_PERIODS.summary": "Périodes MA en jours de bourse séparées par des virgules pour l’analyse de tendance (par défaut 5,10,20,60).",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.indicators.INDICATOR_MA_PERIODS.title": "Périodes des moyennes mobiles",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.indicators.INDICATOR_MA_PERIODS.usage": "Laissez vide pour les valeurs historiques. Ajoutez 120 ou 250 pour le contexte à long terme ; la fenêtre d’analyse s’étend automatiquement jusqu’à la période la plus longue.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.indicators.INDICATOR_MA_PERIODS.valueNotes.0": "Chaque valeur doit être un entier positif inférieur ou égal à 500.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.indicators.INDICATOR_MA_PERIODS.valueNotes.1": "Les périodes configurées apparaissent avec leur libellé MA exact dans ma_by_period et dans l’instantané typé des indicateurs.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.indicators.INDICATOR_MA_PERIODS.valueNotes.2": "S’il y a moins de bougies que la période, la MA est omise et signalée comme données insuffisantes, sans remplacement silencieux par une période plus courte.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.indicators.INDICATOR_RSI_PERIODS.impact.0": "Influe sur les valeurs RSI et la notation de surachat ou survente dans l’analyse de tendance.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.indicators.INDICATOR_RSI_PERIODS.notes.0": "Les champs historiques rsi_6, rsi_12 et rsi_24 gardent toujours leurs périodes exactes et ne sont jamais des alias de position.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.indicators.INDICATOR_RSI_PERIODS.summary": "Périodes RSI séparées par des virgules (par défaut 6,12,24).",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.indicators.INDICATOR_RSI_PERIODS.title": "Périodes RSI",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.indicators.INDICATOR_RSI_PERIODS.usage": "Les valeurs configurées sont affichées avec leur libellé RSI exact. La deuxième valeur, ou la première s’il n’y en a qu’une, pilote les seuils d’état.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.indicators.INDICATOR_RSI_PERIODS.valueNotes.0": "Les périodes doivent être des entiers positifs inférieurs ou égaux à 250.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.indicators.INDICATOR_RSI_PERIODS.valueNotes.1": "Le RSI utilise le lissage Wilder/SMMA, comme le RSI du parcours d’alerte.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.indicators.macd_params.impact.0": "Influe sur le DIF, le DEA, l’histogramme MACD et la notation d’achat ou de vente dérivée.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.indicators.macd_params.notes.0": "Conservez les valeurs par défaut sauf si vous souhaitez modifier volontairement la convention MACD.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.indicators.macd_params.summary": "Périodes EMA rapide, lente et de signal du MACD (par défaut 12/26/9).",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.indicators.macd_params.title": "Périodes MACD",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.indicators.macd_params.usage": "INDICATOR_MACD_FAST doit être inférieur à INDICATOR_MACD_SLOW. Le signal est la période de lissage DEA.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.indicators.macd_params.valueNotes.0": "Le réglage standard est 12/26/9 ; des paires plus courtes réagissent plus vite mais sont plus bruitées.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.indicators.macd_params.valueNotes.1": "Les valeurs explicitement invalides sont refusées de façon cohérente au démarrage et lors de l’enregistrement des réglages.",
  "utils.systemConfigI18n.fieldTitleMaps.INDICATOR_MACD_FAST": "Période MACD rapide",
  "utils.systemConfigI18n.fieldTitleMaps.INDICATOR_MACD_SIGNAL": "Période de signal MACD",
  "utils.systemConfigI18n.fieldTitleMaps.INDICATOR_MACD_SLOW": "Période MACD lente",
